if(document.body.dataset.page==='contact'){document.querySelector('#page-content').innerHTML=hero('Let’s build your order.','Tell us what your business needs. Our wholesale team will help with pricing, MOQ and delivery.','Bulk enquiry')+`<section class="trade-desk section"><div class="wrap trade-layout"><aside class="trade-aside"><span class="eyebrow light">Shama trade desk</span><h2>Wholesale,<br>without the<br><em>guesswork.</em></h2><p>Send one clear requirement and our team will return with availability, minimum quantity and delivery guidance.</p><div class="trade-steps"><div><b>01</b><span>Choose your range</span></div><div><b>02</b><span>Share quantity & location</span></div><div><b>03</b><span>Receive your quotation</span></div></div><div class="trade-direct"><a href="tel:+33143420579"><small>Call the trade desk</small><strong>+33 1 43 42 05 79</strong></a><a href="mailto:info@shamafr.com"><small>Email us</small><strong>info@shamafr.com</strong></a></div></aside><div class="trade-form-wrap"><div class="trade-form-head"><span>Bulk order request</span><b>Usually replies within one business day</b></div><form id="trade-form" class="trade-form"><label>Business / shop name<input name="business" required placeholder="Company name"></label><label>Your name<input name="name" required placeholder="Full name"></label><label>Email<input name="email" type="email" required placeholder="you@company.com"></label><label>Phone / WhatsApp<input name="phone" type="tel" required placeholder="+33 …"></label><label>Product range<select name="category" required><option value="">Choose a range</option>${categories.map(c=>`<option>${c.name}</option>`).join('')}<option>Multiple categories</option></select></label><label>Estimated cases<input name="quantity" type="number" min="1" value="10" required></label><label class="trade-full">Products or pack sizes<input name="products" required placeholder="Example: Basmati Rice 20kg, 30 cases"></label><label>Delivery city<input name="city" required placeholder="City"></label><label>Postcode<input name="postcode" required placeholder="75001"></label><label class="trade-full">Anything else?<textarea name="notes" placeholder="Preferred delivery date, frequency, special requirements…"></textarea></label><div class="trade-send trade-full"><button type="button" class="trade-email"><i>✉</i><span><small>Send enquiry by</small>Email</span><b>↗</b></button><button type="button" class="trade-whatsapp"><i>◉</i><span><small>Send enquiry on</small>WhatsApp</span><b>↗</b></button></div><p class="trade-privacy trade-full">Your details are used only to respond to this wholesale enquiry.</p></form></div></div></section><section class="contact-location"><div class="wrap location-grid"><div><span class="eyebrow">Visit Shama</span><h2>Rosny-sous-Bois,<br>France.</h2></div><div class="location-data"><p>3, allée de l’Espérance<br>93110 Rosny Sous Bois – France</p><p>Mon–Fri 09:00–13:00, 14:00–18:00<br>Sat 09:00–13:00, 14:00–16:00</p></div></div></section>`;const trade=document.querySelector('#trade-form');function tradeText(){if(!trade.reportValidity())return null;const d=new FormData(trade);return `Hello Shama International,\n\nI would like a wholesale quotation.\n\nBusiness: ${d.get('business')}\nContact: ${d.get('name')}\nEmail: ${d.get('email')}\nPhone: ${d.get('phone')}\nRange: ${d.get('category')}\nEstimated cases: ${d.get('quantity')}\nProducts / pack sizes: ${d.get('products')}\nDelivery: ${d.get('city')} ${d.get('postcode')}\nAdditional details: ${d.get('notes')||'None'}\n\nPlease share availability, MOQ, pricing and delivery options.`}document.querySelector('.trade-email').onclick=()=>{const t=tradeText();if(t)location.href=`mailto:info@shamafr.com?subject=${encodeURIComponent('Wholesale enquiry — '+new FormData(trade).get('business'))}&body=${encodeURIComponent(t)}`};document.querySelector('.trade-whatsapp').onclick=()=>{const t=tradeText();if(t)window.open(`https://wa.me/33143420579?text=${encodeURIComponent(t)}`,'_blank','noopener')}}
