function renderBulkCart(){const items=document.querySelector('#cart-items'),empty=document.querySelector('#cart-empty'),count=document.querySelector('#order-count');count.textContent=bulkCart.length;items.innerHTML=bulkCart.map((x,i)=>`<article class="cart-item"><div><strong>${x.product}</strong><small>${x.pack||'Pack size to be confirmed'}</small></div><div class="cart-qty"><button type="button" data-cart-minus="${i}">−</button><span>${x.qty} cases</span><button type="button" data-cart-plus="${i}">+</button></div><button class="cart-remove" type="button" data-cart-remove="${i}">×</button></article>`).join('');empty.hidden=bulkCart.length>0;items.hidden=!bulkCart.length;document.querySelector('.cart-customer').hidden=!bulkCart.length;document.querySelector('.cart-send').hidden=!bulkCart.length;const productField=document.querySelector('#trade-form [name="products"]');if(productField){productField.value=bulkCart.map(x=>`${x.product} — ${x.qty} cases`).join('; ');const q=document.querySelector('#trade-form [name="quantity"]');if(q)q.value=bulkCart.reduce((n,x)=>n+x.qty,0)||1;const c=document.querySelector('#trade-form [name="category"]');if(c)c.value=bulkCart.length?'Multiple categories':''}renderTradePickerSelected()}
